 assert.equal(git('rev-parse',c.originalHead+'^{tree}').trim(),c.originalTree);assert.equal(blob(head,c.originalWitness),c.originalWitnessBlob,'Original615 week witness must remain exact');
 assert.equal(blob(head,'tests/my-timber-recorded-week-activation-composition.test.mjs'),c.originalTestsBlob,'Original615 assertions must remain byteexact');
