 verifyOriginalRecordedWeek(originalRecord,{head:c.originalHead,read:(r,p)=>blob(r==='HEAD'?c.originalHead:r,p),readContent:(r,p)=>content(r==='HEAD'?c.originalHead:r,p),readDiff:diff,isAncestor:ancestor});
 for(const ref of[c.base,c.source,c.maintenanceSource,c.originalHead]){ancestor(ref,head);assert.notEqual(isAncestor(ref,head),false,'Supplied factual-week ancestry changed');}
 for(const[a,b,paths]of[[c.base,c.source,c.paths],[c.source,c.maintenanceSource,c.maintenancePaths],[c.maintenanceSource,head,[manifest]]]){
  ancestor(a,b);assert.notEqual(isAncestor(a,b),false,'Supplied factual-week ancestry changed');assert.deepEqual(sorted(diff(a,b)),sorted(paths),'Unreviewed actual factual-week source boundary');assert.deepEqual(sorted(readDiff(a,b)),sorted(diff(a,b)),'Supplied factual-week diff changed');
 }
 assert.deepEqual(sorted(diff(c.base,head)),sorted([...new Set([...c.paths,...c.maintenancePaths,manifest])]),'Every unrelated source path must remain exact');
 for(const r of['HEAD',head])assert.deepEqual(sorted(readDiff(c.base,r)),sorted(diff(c.base,head)),'Supplied current factual-week diff changed');
 for(const p of[...new Set([...c.paths,...c.maintenancePaths])]){
  const ref=c.maintenancePaths.includes(p)?c.maintenanceSource:c.source;
  assert.equal(blob(head,p),blob(ref,p),'Actual factual-week source drift: '+p);assert.equal(mode(head,p),'100644','Factual-week file mode drift: '+p);
  for(const r of['HEAD',head]){assert.equal(read(r,p),blob(head,p),'Fresh supplied factual-week source drift: '+p);assert.equal(readContent(r,p),content(head,p),'Fresh supplied factual-week content drift: '+p);}
 }
 for(const p of['member-experience','release','docs','.github/workflows'])for(const r of['HEAD',head])assert.equal(read(r,p),blob(head,p),'Fresh supplied factual-week directory source drift: '+p);
 for(const[p,expected]of Object.entries(policy.payloadBlobs)){assert.equal(blob(c.originalSource,p),expected);assert.equal(blob(c.source,p),expected,'Frozen original factual payload required: '+p);}
 for(const[p,expected]of Object.entries(policy.newMaintenanceBlobs))assert.equal(blob(head,p),expected,'Exact bounded live acceptance source required: '+p);
 for(const p of Object.keys(policy.inverses))assert.equal(inverse(p,content(head,p)),content(c.base,p),'Every original machinery assertion outside exact week hooks must remain: '+p);
 const before=JSON.parse(content(c.base,manifest)),after=JSON.parse(content(head,manifest));assert.deepEqual(after[key],c);delete after[key];assert.deepEqual(after,before,'All prior authority, receipt and failure records must remain exact');
 for(const r of['HEAD',head])assert.equal(readContent(r,manifest),content(head,manifest),'Supplied current factual-week ledger drift');assert.equal(readContent(c.base,manifest),content(c.base,manifest),'Supplied prior machinery ledger drift');
 for(const p of['wrangler.jsonc','wrangler.coaching.jsonc']){const config=content(head,p);assert.equal(config.split(RECORDED_WEEK_ACTIVATION_FLAG).length,2);assert.equal(config.replace(RECORDED_WEEK_ACTIVATION_FLAG,''),content(c.base,p),'Only the exact factual-week flag may change configuration');}
 assert.equal(content(head,'wrangler.jsonc'),content(head,'wrangler.coaching.jsonc'),'Core and coaching configs must remain byteidentical');
 for(const p of['frontend','public','member-experience/treatment-week.mjs','member-experience/treatment-patterns.mjs','member-experience/treatment-model.mjs','.github/workflows/cloudflare-production-promote.yml','package.json','package-lock.json','wrangler.hq-management.jsonc']){
  assert.equal(blob(head,p),blob(c.base,p),'Protected factual-week source drift: '+p);for(const r of['HEAD',head])assert.equal(read(r,p),blob(head,p),'Supplied protected factual-week source drift: '+p);
 }
