 const assertCurrent=()=>{clean();assert.equal(currentHead(),rawHead,'Recorded-week source drift: Raw HEAD changed during projection');};
 if(!c)return{rawHead,head:rawHead,record,affected:()=>false,read:sourceReader,blob,content,diff,ancestor,assertCurrent,authentic:(v,r,p)=>authentic(v,r,p,rawHead)};
