 const prior=structuredClone(record);delete prior[key];
 const view={rawHead,head:c.base,record:prior,affected,assertCurrent,authentic:(v,r,p)=>authentic(v,r,p,rawHead),currentContent:content,
  blob:(r,p)=>blob(r==='HEAD'||r===rawHead?c.base:r,p),content:(r,p)=>content(r==='HEAD'||r===rawHead?c.base:r,p),diff,ancestor};
