 return(r,p)=>{if(current(r,view)&&view.head!==view.rawHead){if(!defaultReader){assert(view.authentic(reader('HEAD',p),'HEAD',p),'Recorded-week source drift: Unauthentic supplied HEAD: '+p);assert(view.authentic(reader(view.rawHead,p),view.rawHead,p),'Recorded-week source drift: Unauthentic supplied raw-head: '+p);}return reader(view.head,p);}return reader(defaultReader&&r==='HEAD'?view.rawHead:r,p);};
