export function recordedWeekActivationAuthenticatedContent(reader,view){return(r,p)=>{if(current(r,view)&&view.head!==view.rawHead){assert(view.authentic(reader('HEAD',p),'HEAD',p),'Recorded-week source drift: Unauthentic supplied HEAD content: '+p);assert(view.authentic(reader(view.rawHead,p),view.rawHead,p),'Recorded-week source drift: Unauthentic supplied raw-head content: '+p);return reader(view.head,p);}return reader(r,p);};}
export function recordedWeekActivationAuthenticatedDiff(reader,view){return(a,b)=>{if(current(b,view)&&view.head!==view.rawHead){for(const r of['HEAD',view.rawHead])assert.deepEqual(sorted(reader(a,r)),sorted(diff(a,view.rawHead)),'Recorded-week source drift: Supplied raw diff changed');return reader(a,view.head);}return reader(a,b);};}
export function recordedWeekActivationAuthenticatedAncestor(reader,view){return(a,b)=>{if(current(b,view)&&view.head!==view.rawHead){for(const r of['HEAD',view.rawHead])assert.notEqual(reader(a,r),false,'Recorded-week source drift: Supplied raw ancestry changed');return reader(a,view.head);}return reader(a,b);};}
export function recordedWeekActivationLegacyRead(reader,view){return(r,p)=>{if((r==='HEAD'||r===view.rawHead)&&view.affected(p)){const a=reader('HEAD',p),b=reader(view.rawHead,p);if(a!==b&&!(view.authentic(a,'HEAD',p)&&view.authentic(b,view.rawHead,p)))return r==='HEAD'?a:b;return reader(view.head,p);}return reader(r,p);};}
export function withoutRecordedWeekActivationFlag(config){if(!config.includes(RECORDED_WEEK_ACTIVATION_FLAG))return config;const view=recordedWeekActivationHistoricalView();assert.notEqual(view.rawHead,view.head,'Unregistered week activation flag');assert.equal(config,content(view.rawHead,'wrangler.jsonc'),'Only exact current authorised configuration can be projected');return config.replace(RECORDED_WEEK_ACTIVATION_FLAG,'');}
